"""Credit lines: a commit or tag message line that credits a coding assistant, which a push would make public.

A credit line is a `Co-Authored-By:` or `Assisted-by:` trailer, whoever it names, or a line that opens with
"Generated with" or "Generated by" (after any symbols, such as an emoji). Every such trailer counts, so a new
assistant's name needs no list; a repository with people as co-authors leaves the check off. The check is off unless
`telonion.holdCredits` is true, set for one repository or with --global for every one.
"""
import re

from .scan import commits, git, setting

CREDIT = re.compile(r'^[^\w\n]*(?:co-authored-by\s*:|assisted[-\s]by\s*:|generated[-\s]+(?:with|by)\b)', re.I)


def on(repo):
    return setting(repo, 'holdCredits', '--type=bool')[-1:] == ['true']


def _kind(line):
    low = line.lower()
    return ('a Co-Authored-By line' if 'co-authored-by' in low else 'an Assisted-by line' if 'assisted' in low
            else 'a "Generated" line')


def in_message(text, where='commit message'):
    """[(where, what)] for each credit line in `text`."""
    return [(f'{where} line {n}', _kind(line)) for n, line in enumerate(text.split('\n'), 1) if CREDIT.match(line)]


def in_push(repo, tips, stop=()):
    """[(where, what)] for each credit line in the messages a push of `tips` sends beyond `stop`: every commit's, and
    every tag object's among the tips (a tag of a tag too). Git errors propagate: never a clean reading."""
    found = []
    shas = commits(repo, tips, stop)
    if shas:
        log = git(repo, 'log', '--stdin', '--no-walk=unsorted', '--no-show-signature', '--format=%h%x00%B%x1e',
                  stdin=''.join(s + '\n' for s in shas))
        for rec in log.split('\x1e'):
            if '\x00' in rec:
                short, body = rec.lstrip('\n').split('\x00', 1)
                found += in_message(body, f'commit {short} message')
    seen = set()
    for tip in tips:
        oid = tip
        while oid and oid not in seen:
            seen.add(oid)
            if git(repo, 'cat-file', '-t', oid).strip() != 'tag':
                break
            headers, _, body = git(repo, 'cat-file', 'tag', oid).partition('\n\n')
            fields = dict(line.split(' ', 1) for line in headers.splitlines() if ' ' in line)
            found += in_message(body, f"tag {fields.get('tag', oid[:7])} message")
            oid = fields.get('object', '')
    return found
